\mathsf{SubSeqGraph}_{\kappa\lambda}
=
\{(A,J,\vec x,\vec t,B):|J|<\lambda
\land \vec x:J\to\mathsf{Var}\ \text{为单射}
\land \vec t:J\to\mathsf{Tm}_{\kappa\lambda}^{\Sigma}
\land A\in\mathsf{Fm}_{\kappa\lambda}^{\Sigma}
\land B=\operatorname{SubSeq}_{\kappa\lambda}(A,\vec x,\vec t)\}.

\mathsf{AlphaStep}_{\kappa\lambda}
=
\{(\operatorname{allSeq}(J,\vec x,A),\operatorname{allSeq}(J,\vec z,A[\vec x:=\vec z])):
|J|<\lambda\land \vec z:J\to\mathsf{Var}\ \text{为单射}\ \land
\operatorname{rng}(\vec z)\cap(\operatorname{FV}(A)\cup\operatorname{rng}(\vec x))=\varnothing\}
